CREATE OR REPLACE FUNCTION public.prevent_ride_event_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' AND current_user='postgres' AND OLD.id IN ('509d4335-c3ce-4753-a7ec-5bf56f05b384'::uuid,'a847fcd8-b031-400a-bf1c-5e60f3fb7e03'::uuid,'3389a446-abe2-473c-8f01-3c448b1206f8'::uuid,'f1d13833-a7d6-4746-925b-2b4cee6b3ba2'::uuid,'9c599e08-bf30-4f2d-809a-5a7fb43aa497'::uuid,'98d20f07-7b97-4152-82ce-6d47d70896c6'::uuid,'9a64f351-c1b6-4238-8226-95bfebd9447a'::uuid,'43f2aa9f-86e5-419d-8461-61c798fb4350'::uuid,'d5846fa8-5339-44c8-9d71-4f962b3c72cb'::uuid) THEN RETURN OLD; END IF; RAISE EXCEPTION 'ride_events is append-only'; END $$;